.admin-biometric-firmware-controls {
  display: grid;
  gap: 10px;
}

.admin-biometric-firmware-status {
  margin: 0;
  color: #475569;
  font-size: 11px;
  line-height: 1.45;
}

.admin-biometric-firmware-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.admin-biometric-card--firmware .admin-biometric-limit-note code {
  font: 10px/1.4 Consolas, "Courier New", monospace;
}
